    void sends_the_reference_amount_and_currency_as_json_to_the_authorizations_endpoint() {
        stub(200, "{\"status\":\"approved\"}");

        gateway.authorize("ORD-7", AMOUNT);

        provider.verify(1, postRequestedFor(urlEqualTo("/v1/authorizations"))
                .withHeader("Content-Type", com.github.tomakehurst.wiremock.client.WireMock.containing("application/json"))
                .withRequestBody(equalToJson("{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}", true, false)));
    }

    @Test
    void an_approved_answer_is_read_as_approved() {
        stub(200, "{\"status\":\"approved\"}");

        assertThat(gateway.authorize("ORD-7", AMOUNT)).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_as_declined() {
        stub(200, "{\"status\":\"declined\"}");

        assertThat(gateway.authorize("ORD-7", AMOUNT)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

