        stub(200, "{\"status\":\"approved\",\"id\":\"auth-1\",\"extra\":{\"a\":1}}");

        assertThat(gateway.authorize("ORD-7", AMOUNT)).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_402_refusal_is_a_declined_outcome() {
        stub(402, "{\"error\":\"card_refused\"}");

        assertThat(gateway.authorize("ORD-7", AMOUNT)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_without_a_body_is_a_declined_outcome() {
        stub(402, "");

        assertThat(gateway.authorize("ORD-7", AMOUNT)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_rejected_request_is_reported_as_a_failure_not_a_decline() {
        stub(400, "{\"error\":\"invalid_currency\"}");

        assertThatThrownBy(() -> gateway.authorize("ORD-7", AMOUNT))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_outage_is_reported_as_a_failure_not_a_decline() {
        stub(503, "");

        assertThatThrownBy(() -> gateway.authorize("ORD-7", AMOUNT))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }

    @Test
    void an_unknown_status_is_never_treated_as_approved() {
        stub(200, "{\"status\":\"pending\"}");

        assertThat(gateway.authorize("ORD-7", AMOUNT)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_answer_without_a_status_is_never_treated_as_approved() {
        stub(200, "{}");

        assertThat(gateway.authorize("ORD-7", AMOUNT)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    private void stub(int status, String body) {
        provider.stubFor(post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse()
                        .withStatus(status)
                        .withHeader("Content-Type", "application/json")
                        .withBody(body)));
    }
}
